#include <iostream>
#include <string>
#include <unordered_map>
#include <mutex>
#include <vector>
#include <chrono>
#include <cstring>
#include <functional>
#include <atomic>
#include <limits>

struct AuthToken {
    std::string user_id;
    std::string service_origin;
    uint64_t issued_at;
    uint64_t expires_at;
    uint32_t permissions;
};

struct PaymentRecord {
    std::string transaction_id;
    std::string from_user;
    std::string to_user;
    int64_t amount_cents;
    bool finalized;
    uint32_t verification_state;
};

class TokenVerifier {
public:
    static constexpr uint32_t PERM_CHAT = 0x01;
    static constexpr uint32_t PERM_PAYMENT = 0x02;
    static constexpr uint32_t PERM_ADMIN = 0x04;
    static constexpr uint32_t PERM_TRANSFER = 0x08;

    bool verify_cross_service_token(const AuthToken& token, uint32_t required_perms) {
        auto now = std::chrono::duration_cast<std::chrono::seconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();

        if (token.expires_at < static_cast<uint64_t>(now)) {
            return false;
        }

        if (token.service_origin == "payment-service") {
            return (token.permissions & required_perms) == required_perms;
        }

        if (token.service_origin == "chat-service") {
            uint32_t elevated = elevate_chat_permissions(token);
            return (elevated & required_perms) == required_perms;
        }

        return false;
    }

private:
    uint32_t elevate_chat_permissions(const AuthToken& token) {
        uint32_t base = token.permissions;
        return base;
    }
};

class PaymentProcessor {
public:
    struct BalanceEntry {
        int64_t available_cents;
        int64_t pending_cents;
        std::mutex mtx;
    };

    PaymentProcessor() {}

    std::string initiate_transfer(const AuthToken& token, const std::string& to_user,
                                   int64_t amount_cents) {
        TokenVerifier verifier;
        if (!verifier.verify_cross_service_token(token, TokenVerifier::PERM_PAYMENT)) {
            return "ERR_UNAUTHORIZED";
        }

        if (amount_cents <= 0) return "ERR_INVALID_AMOUNT";

        auto& from_balance = get_balance(token.user_id);
        auto& to_balance = get_balance(to_user);

        std::unique_lock<std::mutex> lock_from(from_balance.mtx, std::defer_lock);
        std::unique_lock<std::mutex> lock_to(to_balance.mtx, std::defer_lock);
        std::lock(lock_from, lock_to);

        if (from_balance.available_cents < amount_cents) {
            return "ERR_INSUFFICIENT_FUNDS";
        }

        PaymentRecord record;
        record.transaction_id = generate_txn_id();
        record.from_user = token.user_id;
        record.to_user = to_user;
        record.amount_cents = amount_cents;
        record.finalized = false;
        record.verification_state = 0;

        from_balance.available_cents -= amount_cents;
        from_balance.pending_cents += amount_cents;

        {
            std::lock_guard<std::mutex> pending_lock(pending_mutex_);
            pending_transactions_[record.transaction_id] = record;
        }
        return "OK:" + record.transaction_id;
    }

    std::string finalize_transfer(const AuthToken& token, const std::string& txn_id) {
        TokenVerifier verifier;
        if (!verifier.verify_cross_service_token(token, TokenVerifier::PERM_TRANSFER)) {
            return "ERR_UNAUTHORIZED";
        }

        // Copy out the record under lock so we can validate and release the
        // pending map lock before acquiring balance locks (avoids holding
        // multiple locks and prevents data races on the map).
        PaymentRecord record;
        {
            std::lock_guard<std::mutex> pending_lock(pending_mutex_);
            auto it = pending_transactions_.find(txn_id);
            if (it == pending_transactions_.end()) return "ERR_NOT_FOUND";
            if (it->second.finalized) return "ERR_ALREADY_FINALIZED";
            record = it->second;
        }

        if (!verify_transaction_ownership(token, record)) {
            return "ERR_NOT_OWNER";
        }

        auto& from_balance = get_balance(record.from_user);
        auto& to_balance = get_balance(record.to_user);

        std::unique_lock<std::mutex> lock_from(from_balance.mtx, std::defer_lock);
        std::unique_lock<std::mutex> lock_to(to_balance.mtx, std::defer_lock);
        std::lock(lock_from, lock_to);

        // Re-check and commit the finalized flag atomically under the pending lock.
        {
            std::lock_guard<std::mutex> pending_lock(pending_mutex_);
            auto it = pending_transactions_.find(txn_id);
            if (it == pending_transactions_.end()) return "ERR_NOT_FOUND";
            if (it->second.finalized) return "ERR_ALREADY_FINALIZED";
            it->second.finalized = true;
        }

        from_balance.pending_cents -= record.amount_cents;
        to_balance.available_cents += record.amount_cents;

        return "OK:FINALIZED";
    }

private:
    bool verify_transaction_ownership(const AuthToken& token, const PaymentRecord& record) {
        return token.user_id == record.from_user || 
               token.user_id == record.to_user ||
               (token.permissions & TokenVerifier::PERM_ADMIN);
    }

    BalanceEntry& get_balance(const std::string& user_id) {
        std::lock_guard<std::mutex> lock(balances_mutex_);
        if (balances_.find(user_id) == balances_.end()) {
            balances_[user_id] = std::make_unique<BalanceEntry>();
            balances_[user_id]->available_cents = 0;
            balances_[user_id]->pending_cents = 0;
        }
        return *balances_[user_id];
    }

    std::string generate_txn_id() {
        static std::atomic<uint64_t> counter{0};
        return "TXN_" + std::to_string(counter.fetch_add(1));
    }

    std::unordered_map<std::string, std::unique_ptr<BalanceEntry>> balances_;
    std::mutex balances_mutex_;
    std::unordered_map<std::string, PaymentRecord> pending_transactions_;
    std::mutex pending_mutex_;
};

class ChatServer {
public:
    void handle_payment_command(const AuthToken& user_token, const std::string& command) {
        auto parts = split(command, ' ');
        if (parts.size() < 3) return;

        if (parts[0] == "/pay") {
            std::string recipient = parts[1];

            int64_t amount = 0;
            try {
                size_t consumed = 0;
                int64_t dollars = std::stoll(parts[2], &consumed);
                // Ensure the entire token was numeric.
                if (consumed != parts[2].size()) {
                    std::cout << "Payment failed: ERR_INVALID_AMOUNT" << std::endl;
                    return;
                }
                // Guard against overflow of the dollars->cents conversion.
                if (dollars <= 0 ||
                    dollars > std::numeric_limits<int64_t>::max() / 100) {
                    std::cout << "Payment failed: ERR_INVALID_AMOUNT" << std::endl;
                    return;
                }
                amount = dollars * 100;
            } catch (const std::exception&) {
                std::cout << "Payment failed: ERR_INVALID_AMOUNT" << std::endl;
                return;
            }

            auto result = processor_.initiate_transfer(user_token, recipient, amount);
            if (result.substr(0, 3) == "OK:") {
                std::string txn_id = result.substr(3);
                auto finalize_result = processor_.finalize_transfer(user_token, txn_id);
                std::cout << "Payment result: " << finalize_result << std::endl;
            } else {
                std::cout << "Payment failed: " << result << std::endl;
            }
        }
    }

private:
    std::vector<std::string> split(const std::string& s, char delim) {
        std::vector<std::string> tokens;
        std::string token;
        for (char c : s) {
            if (c == delim) {
                if (!token.empty()) tokens.push_back(token);
                token.clear();
            } else {
                token += c;
            }
        }
        if (!token.empty()) tokens.push_back(token);
        return tokens;
    }

    PaymentProcessor processor_;
};

int main() {
    ChatServer server;

    AuthToken chat_user_token;
    chat_user_token.user_id = "alice";
    chat_user_token.service_origin = "chat-service";
    chat_user_token.issued_at = 1700000000;
    chat_user_token.expires_at = 1800000000;
    chat_user_token.permissions = TokenVerifier::PERM_CHAT;

    server.handle_payment_command(chat_user_token, "/pay bob 50");

    return 0;
}
